import math
from collections import Counter
from typing import List, Optional, Union


class Statistics3:
    """
    This class implements methods for calculating indicators such as median, mode,
    correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data: List[Union[int, float]]) -> Optional[float]:
        """
        Calculates the median of the given list.
        """
        if not data:
            return None
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 1:
            return float(sorted_data[mid])
        else:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0

    @staticmethod
    def mode(data: List[Union[int, float]]) -> List[Union[int, float]]:
        """
        Calculates the mode of the given list.
        """
        if not data:
            return []
        counts = Counter(data)
        max_count = max(counts.values())
        return [value for value, count in counts.items() if count == max_count]

    @staticmethod
    def correlation(x: List[Union[int, float]], y: List[Union[int, float]]) -> Optional[float]:
        """
        Calculates the Pearson correlation coefficient between two lists.
        """
        if len(x) != len(y) or not x:
            return None
        n = len(x)
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        numerator = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
        denom_x = sum((xi - mean_x) ** 2 for xi in x)
        denom_y = sum((yi - mean_y) ** 2 for yi in y)
        denominator = math.sqrt(denom_x * denom_y)
        if denominator == 0:
            return None
        return numerator / denominator

    @staticmethod
    def mean(data: List[Union[int, float]]) -> Optional[float]:
        """
        Calculates the mean of the given list.
        """
        if not data:
            return None
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data: List[List[Union[int, float]]]) -> List[List[Optional[float]]]:
        """
        Calculates the correlation matrix of the given 2D list.
        Each row and column corresponds to a variable (column in the input).
        """
        if not data or not data[0]:
            return []

        num_vars = len(data[0])
        matrix: List[List[Optional[float]]] = []

        for i in range(num_vars):
            row: List[Optional[float]] = []
            for j in range(num_vars):
                column_i = [row[i] for row in data]
                column_j = [row[j] for row in data]
                corr = Statistics3.correlation(column_i, column_j)
                row.append(corr)
            matrix.append(row)

        return matrix

    @staticmethod
    def standard_deviation(data: List[Union[int, float]]) -> Optional[float]:
        """
        Calculates the sample standard deviation of the given list.
        """
        n = len(data)
        if n < 2:
            return None
        mean_val = Statistics3.mean(data)
        variance = sum((x - mean_val) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data: List[Union[int, float]]) -> Optional[List[float]]:
        """
        Calculates the z-score of the given list.
        """
        if not data:
            return None
        mean_val = Statistics3.mean(data)
        std_dev = Statistics3.standard_deviation(data)
        if std_dev is None or std_dev == 0:
            return None
        return [(x - mean_val) / std_dev for x in data]
